mapper.select:
SELECT pm.project_id
FROM project_member pm
WHERE pm.user_id = #{userId}
  AND pm.is_deleted = 0

  AND pm.member_role = #{memberRole}

ORDER BY pm.project_id DESC

SELECT cp.project_id, cp.project_name, cp.team_name, cp.status, cp.completion_rate, cp.deadline, leader.real_name AS leader_name, cn.title AS notice_title FROM project_member pm JOIN competition_project cp ON cp.project_id = pm.project_id AND cp.is_deleted = 0 JOIN sys_user leader ON leader.user_id = cp.leader_id AND leader.is_deleted = 0 JOIN competition_notice cn ON cn.notice_id = cp.notice_id AND cn.is_deleted = 0 WHERE pm.user_id = #{userId} AND pm.is_deleted = 0
AND pm.member_role = #{memberRole}
ORDER BY cp.project_id DESC

SELECT DISTINCT cp.project_id, cp.project_name, cp.team_name, cp.status, cp.completion_rate, cp.deadline, leader.real_name AS leader_name, cn.title AS notice_title FROM project_member pm JOIN competition_project cp ON cp.project_id = pm.project_id AND cp.is_deleted = 0 JOIN sys_user leader ON leader.user_id = cp.leader_id AND leader.is_deleted = 0 JOIN competition_notice cn ON cn.notice_id = cp.notice_id AND cn.is_deleted = 0 WHERE pm.user_id = #{userId} AND pm.is_deleted = 0
AND pm.member_role = #{memberRole}
AND (cp.project_name LIKE CONCAT('%', #{keyword}, '%') OR cn.title LIKE CONCAT('%', #{keyword}, '%'))
AND cp.status = #{status}
AND cp.deadline <= #{deadlineBefore}
ORDER BY cp.project_id DESC
